from math import isqrt, gcd
import sys
sys.setrecursionlimit(10000)

def fl(k, a, b, c):
    # floor(k*(a+b*sqrt2)/c), c>0, exact
    m = k * b
    if m >= 0:
        t = isqrt(2 * m * m)
    else:
        r = isqrt(2 * m * m)
        t = -r if r * r == 2 * m * m else -r - 1
    return (k * a + t) // c

def norm(a, b, c):
    if c < 0:
        a, b, c = -a, -b, -c
    g = gcd(gcd(abs(a), abs(b)), c)
    return a // g, b // g, c // g

def S(a, b, c, n):
    # sum_{k=1}^n floor(k*alpha), alpha=(a+b*sqrt2)/c > 0 irrational
    if n <= 0:
        return 0
    q = fl(1, a, b, c)
    res = q * n * (n + 1) // 2
    a -= q * c
    m = fl(n, a, b, c)
    if m == 0:
        return res
    d = a * a - 2 * b * b
    A, B, C = norm(c * a, -c * b, d)
    return res + n * m - S(A, B, C, m)

def f(p):
    n = int(p['n'])
    # floor(x) mod 2 = floor(x) - 2*floor(x/2)
    return n - S(0, 1, 1, n) + 2 * S(0, 1, 2, n)

